ard ?> p-5 sm:p-6" method="post" action="/admin/customers/<?= $customerId ?>/profile"><div class="mb-5 flex items-center gap-3"><span class="flex size-10 items-center justify-center rounded-xl bg-blue-50 text-blue-800"><span class="material-symbols-outlined" aria-hidden="true">person</span></span><h3 class="text-lg font-bold text-slate-950">Thông tin người dùng</h3></div><?= Csrf::field() ?><div class="grid gap-4"><label class="text-sm font-semibold text-slate-800">Họ và tên<input class="<?= $field ?> mt-2" name="name" value="<?= ViewHelper::escape($customer['name']) ?>" required maxlength="120"></label><label class="text-sm font-semibold text-slate-800">Email<input class="<?= $field ?> mt-2" name="email" type="email" value="<?= ViewHelper::escape($customer['email']) ?>" required maxlength="190"></label><label class="text-sm font-semibold text-slate-800">Số điện thoại<input class="<?= $field ?> mt-2" name="phone" value="<?= ViewHelper::escape($customer['phone'] ?? '') ?>" maxlength="30"></label><label class="text-sm font-semibold text-slate-800">Địa chỉ<textarea class="<?= $field ?> mt-2 min-h-24 resize-y" name="address" rows="3" maxlength="255"><?= ViewHelper::escape($customer['address'] ?? '') ?></textarea></label></div><button class="<?= $button ?> mt-5 bg-orange-700 text-white hover:bg-orange-800" type="submit"><span class="material-symbols-outlined text-[17px]" aria-hidden="true">save</span>Lưu thông tin</button></form><div class="space-y-6"><section class="<?= $card ?> p-5 sm:p-6"><div class="mb-3 flex items-center gap-3"><span class="flex size-10 items-center justify-center rounded-xl <?= $isBlocked ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700' ?>"><span class="material-symbols-outlined" aria-hidden="true">admin_panel_settings</span></span><h3 class="text-lg font-bold text-slate-950">Quyền mua</h3></div><p class="text-sm leading-6 text-slate-500">Khi khóa, khách hàng không thể thêm sách vào giỏ hoặc đặt đơn mới.</p><form class="mt-4" method="post" action="/admin/customers/<?= $customerId ?>/purchase-status"><?= Csrf::field() ?><input type="hidden" name="purchase_status" value="<?= $isBlocked ? 'active' : 'blocked' ?>"><button class="<?= $button ?> <?= $isBlocked ? 'bg-emerald-700 text-white hover:bg-emerald-800' : 'bg-red-700 text-white hover:bg-red-800' ?>" type="submit"><?= $isBlocked ? 'Mở lại quyền mua' : 'Khóa quyền mua' ?></button></form></section><section class="<?= $card ?> p-5 sm:p-6"><div class="mb-3 flex items-center gap-3"><span class="flex size-10 items-center justify-center rounded-xl bg-orange-50 text-orange-700"><span class="material-symbols-outlined" aria-hidden="true">account_balance_wallet</span></span><h3 class="text-lg font-bold text-slate-950">Cộng hoặc trừ tiền</h3></div><p class="text-sm leading-6 text-slate-500">Số dư không được phép âm. Mỗi thay đổi bắt buộc có lý do.</p><form class="mt-4 grid gap-4" method="post" action="/admin/customers/<?= $customerId ?>/wallet"><?= Csrf::field() ?><label class="text-sm font-semibold text-slate-800">Số tiền điều chỉnh <span class="font-normal text-slate-500">(VNĐ, âm để trừ)</span><input class="<?= $field ?> mt-2" name="amount" type="number" step="1" min="-<?= (int)$customer['wallet_balance'] ?>" placeholder="100000 hoặc -50000" required></label><label class="text-sm font-semibold text-slate-800">Lý do<input class="<?= $field ?> mt-2" name="description" maxlength="255" placeholder="Hoàn tiền đơn hàng" required></label><button class="<?= $button ?> bg-orange-700 text-white hover:bg-orange-800" type="submit">Cập nhật số dư</button></form></section></div></div><section class="<?= $card ?> overflow-hidden"><div class="border-b border-slate-200 px-5 py-5 sm:px-6"><p class="text-[11px] font-bold uppercase tracking-[0.15em] text-slate-500">Đối soát</p><h3 class="mt-1 text-lg font-bold text-slate-950">Lịch sử ví gần đây</h3></div><?php if (empty($walletHistory)): ?><p class="p-6 text-sm text-slate-500">Chưa có giao dịch điều chỉnh số dư.</p><?php else: ?><div class="overflow-x-auto"><table class="w-full min-w-[800px] border-collapse text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-[0.1em] text-slate-500"><tr><th class="px-4 py-4">Thời gian</th><th class="px-4 py-4">Biến động</th><th class="px-4 py-4">Số dư sau giao dịch</th><th class="px-4 py-4">Lý do</th><th class="px-4 py-4">Người thực hiện</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($walletHistory as $transaction): ?><tr class="text-slate-700"><td class="px-4 py-4 text-xs text-slate-500"><?= ViewHelper::escape($transaction['created_at']) ?></td><td class="px-4 py-4 font-bold <?= (int)$transaction['amount'] >= 0 ? 'text-emerald-700' : 'text-red-700' ?>"><?= (int)$transaction['amount'] >= 0 ? '+' : '' ?><?= ViewHelper::money((int)$transaction['amount']) ?></td><td class="px-4 py-4"><?= ViewHelper::money((int)$transaction['balance_after']) ?></td><td class="max-w-[280px] whitespace-normal px-4 py-4 leading-6"><?= ViewHelper::escape($transaction['description']) ?></td><td class="px-4 py-4 text-slate-500"><?= ViewHelper::escape($transaction['created_by_name'] ?? 'Hệ thống') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>